selector_to_html = {"a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u652f\u6301\u8fb9\u754c<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p>\u5b9e\u73b0\u4e86\u67d0\u4e2a\u7279\u6027\uff0c\u4e0d\u7b49\u4e8e\u5728\u751f\u4ea7\u73af\u5883\u4e2d\u652f\u6301\u5b83\u3002FlagQuantum \u4f1a\u516c\u5f00\u6bcf\u4e2a\u80fd\u529b\u6240\u5904\u7684\u7b49\u7ea7\u2014\u2014\u53d1\u5e03\u8ba4\u8bc1\u3001\u751f\u4ea7\u652f\u6301\u3001\u5f00\u53d1\u8bc1\u636e\u6216\u5b9e\u9a8c\u6027\u2014\u2014\u89c1<a class=\"reference internal\" href=\"../reference/capabilities.html\"><span class=\"std std-doc\">\u80fd\u529b\u53c2\u8003</span></a>\uff1b\u5df2\u9a8c\u8bc1\u7684\u5de5\u4f5c\u6d41\u4e0e\u4ecd\u5c5e\u7814\u7a76\u76ee\u6807\u7684\u90e8\u5206\u90fd\u5728\u90a3\u91cc\u5217\u51fa\uff0c\u800c\u4e0d\u662f\u9760\u793a\u4f8b\u53bb\u6697\u793a\u3002</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5173\u952e\u6982\u5ff5<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>\u89c4\u5212\u4e0d\u662f\u6267\u884c\u8bc1\u636e\u3002\u89c4\u5212\u63cf\u8ff0\u610f\u56fe\u4e0e\u4f30\u8ba1\uff1b\u8fd0\u884c\u65f6\u8bb0\u5f55\u63cf\u8ff0\u5b9e\u9645\u6267\u884c\u4e86\u4ec0\u4e48\u3002</p>", "a[href=\"../reference/capabilities.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u80fd\u529b\u53c2\u8003<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum \u516c\u5f00\u6bcf\u4e2a\u80fd\u529b\u7684\u6210\u719f\u5ea6\uff0c\u800c\u4e0d\u662f\u9760\u793a\u4f8b\u53bb\u6697\u793a\u3002\u672c\u9875\u662f\u6458\u8981\uff1b\u4ed3\u5e93\u4e2d\u7ecf\u673a\u5668\u6821\u9a8c\u7684\u80fd\u529b\u77e9\u9635\u624d\u662f\u6743\u5a01\u6765\u6e90\u3002</p>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u9002\u7528\u4eba\u7fa4<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e3a\u4ec0\u4e48\u9700\u8981 FlagQuantum\uff1f<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>\u968f\u7740\u91cf\u5b50\u7ebf\u8def\u7684\u6bd4\u7279\u6570\u4e0e\u6df1\u5ea6\u589e\u957f\uff0c\u7cbe\u786e\u6a21\u62df\u7684\u6210\u672c\u4f1a\u53d8\u5f97\u96be\u4ee5\u4e3a\u7ee7\uff1b\u800c\u628a\u5df2\u7ecf\u8dd1\u901a\u7684\u6a21\u578b\u642c\u5230\u771f\u5b9e\u786c\u4ef6\u4e0a\uff0c\u901a\u5e38\u610f\u5473\u7740\u91cd\u5199\u3002FlagQuantum \u7528\u540c\u4e00\u5957\u516c\u5f00\u6a21\u578b\u540c\u65f6\u89e3\u51b3\u8fd9\u4e24\u4e2a\u95ee\u9898\uff1a</p>", "a[href=\"#flagquantum\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagQuantum \u6982\u89c8<a class=\"headerlink\" href=\"#flagquantum\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum \u662f\u6784\u5efa\u5728 PyTorch \u4e4b\u4e0a\u7684\u5206\u7247\u3001\u53ef\u5fae\u91cf\u5b50\u6a21\u62df\u4e0e\u8bad\u7ec3\u6846\u67b6\u3002\u5b83\u628a\u91cf\u5b50\u7ebf\u8def\u53d8\u6210\u53ef\u8bad\u7ec3\u6a21\u578b\uff0c\u8ba9\u540c\u4e00\u4efd\u7a0b\u5e8f\u5728\u591a\u79cd\u6a21\u62df\u8868\u793a\u4e4b\u95f4\u5207\u6362\uff0c\u5e76\u901a\u8fc7 FlagOS \u89e6\u8fbe\u56fd\u4ea7\u52a0\u901f\u5668\u3002FlagQuantum \u662f FlagOS \u751f\u6001\u7684\u4e00\u90e8\u5206\u2014\u2014FlagOS \u662f\u4e00\u5957\u7edf\u4e00\u7684\u5f00\u6e90 AI \u7cfb\u7edf\u8f6f\u4ef6\u6808\uff0c\u901a\u8fc7\u65e0\u7f1d\u6574\u5408\u5404\u7c7b\u6a21\u578b\u3001\u7cfb\u7edf\u4e0e\u82af\u7247\u6765\u6784\u5efa\u5f00\u653e\u6280\u672f\u751f\u6001\u3002</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e00\u4efd\u7a0b\u5e8f\uff0c\u591a\u4e2a\u6267\u884c\u76ee\u6807<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>\u67b6\u6784\u4e0a\u7684\u4e0d\u53d8\u5f0f\u5f88\u7b80\u5355\uff1a\u540e\u7aef\u9009\u62e9\u53ef\u4ee5\u6539\u53d8\u6267\u884c\u65b9\u5f0f\uff0c\u4f46\u4e0d\u5f97\u6539\u53d8\u7a0b\u5e8f\u7684\u542b\u4e49\u6216\u7ed3\u679c\u5951\u7ea6\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

